mapper.select:
SELECT 
FROM admin_user u JOIN admin_group g ON g.id = u.group_id
WHERE u.id = #{id}

mapper.update:
UPDATE admin_user SET name = #{name}, dept = #{dept}, phone = #{phone}, group_id = #{groupId},
                      status = #{status}, updated_at = now()
WHERE id = #{id}

UPDATE admin_user SET password_hash = #{passwordHash}, must_change_password = TRUE, failed_count = 0,
                      locked_until = NULL, updated_at = now()
WHERE id = #{id}

mapper.sql:
WHERE created_at >= #{from} AND created_at < #{to}
AND kind = #{kind}
AND login_id = #{loginId}
AND action = #{action}
